//! 🌱️ A retained original UI arena value lends bounded nodes into canonical framework values and returns before release.
use super::*;
use super::collection_arena::UiPageSlot;
use semio_framework_value::{DslValue,Number,OriginalRetirementPoll,RetainedAllocationEffect,RetainedCloneProgress,RetainedCloneStep,RetainedWorkOutcome,RetainedWorkPoll,RetirementDemand,ValueError,ValueRefusalKind,retained_clone::{NativeAllocationIdentity,RetainedCloneClose,retained_clone_grant_admits}};
use semio_framework_job::{StepContext,OriginalSourceBinding,OriginalTurnFailure,close_original_effect_step,receive_original_retained_work};
use std::mem::ManuallyDrop;
fn pay(effect:&mut RetainedAllocationEffect<'_>)->Result<(),ValueError>{if effect.performed(1)?{Ok(())}else{Err(ValueError::literal(ValueRefusalKind::WorkLimit,"original UI action exceeded its original work"))}}
/// 🪙️ One forward original UI action runs inside the turn's own performed-work effect and the single work debit settles after it.
fn turn(cx:&mut StepContext<'_>,d:RetirementDemand,run:impl FnOnce(&mut RetainedAllocationEffect<'_>)->Result<RetainedCloneProgress,ValueError>)->Result<bool,OriginalTurnFailure>{
 cx.original_source_parent()?.validate_borrowed_context(cx)?;
 if cx.is_cancelled()||cx.should_yield()||cx.fuel_remaining()==0||!retained_clone_grant_admits(cx.retained_grant(),d){return Ok(false)}
 let grant=cx.retained_grant();
 let Some((result,performed))=cx.with_original_effect(grant,|_,effect|run(effect))?else{return Ok(false)};
 receive_original_retained_work(cx,RetainedWorkOutcome{result:result.map(RetainedCloneStep::Progress),work:performed})?;Ok(true)
}
fn closed(effect:&RetainedAllocationEffect<'_>,result:Result<RetainedCloneStep,ValueError>)->OriginalRetirementPoll{RetainedWorkPoll::Complete(RetainedWorkOutcome{result:result.map_err(Into::into),work:effect.performed_work()})}
fn begun<E:Into<semio_framework_value::OriginalRetirementFailure>>(turn:RetainedWorkOutcome<Option<RetainedCloneStep>,E>)->OriginalRetirementPoll{RetainedWorkPoll::Complete(RetainedWorkOutcome{result:turn.result.map(|step|step.unwrap_or(RetainedCloneStep::Progress(Default::default()))).map_err(Into::into),work:turn.work})}
fn page_failure(reason:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::OwnershipLimit,reason)}
fn release_receipt(progress:PagedListProgress)->RetainedCloneProgress{RetainedCloneProgress{copied_items:usize::from(progress.progressed),released_bytes:progress.released_allocation_bytes,..Default::default()}}
fn reserved(turn:RetainedWorkOutcome<PagedListReservationOutcome<RetainedCloneProgress>,PagedListReservationFailure>)->Result<RetainedCloneProgress,ValueError>{match turn.result{Ok(PagedListReservationOutcome::Ready(progress))=>Ok(progress),Ok(PagedListReservationOutcome::Denied)=>Ok(Default::default()),Err(PagedListReservationFailure::Work(error))=>Err(error),Err(PagedListReservationFailure::Allocation{error,..})=>Err(page_failure(error.reason))}}
fn released(turn:RetainedWorkOutcome<PagedListReleaseOutcome,PagedListReleaseFailure>)->Result<RetainedCloneProgress,ValueError>{match turn.result{Ok(PagedListReleaseOutcome::Ready(progress))=>Ok(release_receipt(progress)),Ok(PagedListReleaseOutcome::Denied)=>Ok(Default::default()),Err(PagedListReleaseFailure::Work(error))=>Err(error),Err(PagedListReleaseFailure::Release(error))=>Err(page_failure(error.reason))}}
#[derive(Clone,Copy,semio_framework_value::RetireOwned)]
enum Location{Root,Page{index:usize,epoch:u64}}
#[derive(semio_framework_value::RetireOwned)]
struct Frame{location:Location,phase:u8,length:usize,index:usize,next:usize,offset:usize,value:Option<DslValue>,key:Option<String>}
impl Frame{fn new(location:Location)->Self{Self{location,phase:0,length:0,index:0,next:UI_VALUE_NONE,offset:0,value:None,key:None}}}
#[derive(Clone,Copy)]
enum Kind{Null,Bool(bool),Number(f64),Text,List,Map}
#[derive(Clone,Copy)]
struct Info{kind:Kind,length:usize,head:usize}
/// 🧷️ The original root, authentic arena page epochs and actual decoder stay owned until output and source handback finish.
pub struct OriginalUiValueConversion{binding:OriginalSourceBinding,decoder:(NativeAllocationIdentity,u64),slot:usize,body:usize,input:ManuallyDrop<Option<UiValue>>,frames:fixed_list_storage::PagedList<Frame,UI_VALUE_NESTING_DEPTH>,pending:ManuallyDrop<Option<Frame>>,output:ManuallyDrop<Option<DslValue>>,retirement:RetainedCloneClose,started:bool,finished:bool,closing:bool}
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"original UI conversion lost its input slot, arena page, or receiving continuation")}
fn page_error(_:PagedListError)->ValueError{invalid()}
fn header<T>()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<T>(),depth:1,..Default::default()}}
fn receipt(d:RetirementDemand)->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,released_bytes:d.release_bytes}}
const META:usize=size_of::<(usize,u8)>();
const ATTACH:usize=2*size_of::<Option<Frame>>()+2*size_of::<DslValue>()+2*size_of::<String>()+META;
impl OriginalUiValueConversion{
 pub fn birth_demands()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<Self>()+2*size_of::<Option<UiValue>>(),capacity_bytes:size_of::<Self>(),depth:1,..Default::default()}}
 /// 📥️ The actual receiving slot donates its exact root without an arena alias or payload clone.
 pub fn admit(input:&mut Option<UiValue>,cx:&mut StepContext<'_>,output:&mut Option<Box<Self>>)->Result<bool,OriginalTurnFailure>{if input.is_none()||output.is_some(){return Err(invalid().into())}let binding=OriginalSourceBinding::borrow(cx);let slot=input as*mut _ as usize;let body=cx.retained_grant().maximum_copy_bytes;let decoder=cx.native_receiving_identity().ok_or_else(invalid)?;let d=Self::birth_demands();turn(cx,d,|effect|{pay(effect)?;*output=Some(Box::write(Box::new_uninit(),Self{binding,decoder,slot,body,input:ManuallyDrop::new(input.take()),frames:fixed_list_storage::PagedList::empty(),pending:ManuallyDrop::new(None),output:ManuallyDrop::new(None),retirement:Default::default(),started:false,finished:false,closing:false}));Ok(receipt(d))})}
 fn validate(&self,input:&mut Option<UiValue>,cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{if input as*mut _ as usize!=self.slot||!self.binding.matches(cx)||cx.native_receiving_identity()!=Some(self.decoder){return Err(invalid().into())}if self.input.is_some()&&input.is_some(){return Err(invalid().into())}Ok(())}
 fn with_value<R>(&self,location:Location,read:impl FnOnce(&UiValue,Option<&UiValueArena>)->Result<R,ValueError>)->Result<Option<R>,ValueError>{let root=self.input.as_ref().ok_or_else(invalid)?;if matches!(location,Location::Root)&&!matches!(root,UiValue::List(_)|UiValue::Map(_)){return read(root,None).map(Some)}let arena=match ui_value_arena_registry().borrow() {Ok(Some(arena)) =>arena,Ok(None) =>return Ok(None),Err(_) =>return Err(invalid())};match location{Location::Root=>read(root,Some(&arena)).map(Some),Location::Page{index,epoch}=>{let page=arena.pages.get(index).filter(|page|page.epoch==epoch).ok_or_else(invalid)?;let value=match page.value.as_ref().ok_or_else(invalid)?{UiPageValue::List(value)|UiPageValue::Map(_,value)=>value};read(value,Some(&arena)).map(Some)}}}
 fn info(&self,location:Location)->Result<Option<Info>,ValueError>{self.with_value(location,|value,arena|{let(kind,length,handle)=match value{UiValue::Null=>(Kind::Null,0,None),UiValue::Bool(value)=>(Kind::Bool(*value),0,None),UiValue::Number(value)=>(Kind::Number(*value),0,None),UiValue::Text(text)=>(Kind::Text,text.len(),None),UiValue::List(list)=>(Kind::List,list.len(),list.handle),UiValue::Map(map)=>(Kind::Map,map.len(),map.handle)};let head=if let Some(handle)=handle{let collection=arena.and_then(|arena|arena.collection(handle)).filter(|row|!row.retiring&&row.items==length).ok_or_else(invalid)?;collection.head}else{if matches!(kind,Kind::List|Kind::Map)&&length!=0{return Err(invalid())}UI_VALUE_NONE};Ok(Info{kind,length,head})})}
 fn with_page<R>(&self,index:usize,read:impl FnOnce(&UiPageSlot)->Result<R,ValueError>)->Result<Option<R>,ValueError>{let arena=match ui_value_arena_registry().borrow() {Ok(Some(arena)) =>arena,Ok(None) =>return Ok(None),Err(_) =>return Err(invalid())};read(arena.pages.get(index).filter(|page|page.value.is_some()).ok_or_else(invalid)?).map(Some)}
 fn text(&self,location:Location,offset:usize)->Result<Option<([u8;64],usize)>,ValueError>{self.with_value(location,|value,_|{let UiValue::Text(text)=value else{return Err(invalid())};fragment(text.as_str(),offset)})}
 fn key(&self,page:usize,offset:usize)->Result<Option<([u8;64],usize,usize)>,ValueError>{self.with_page(page,|page|{let Some(UiPageValue::Map(key,_))=page.value.as_ref()else{return Err(invalid())};let(bytes,count)=fragment(key.as_str(),offset)?;Ok((bytes,count,key.len()))})}
 fn reserve_demands(&self)->Result<RetirementDemand,ValueError>{Ok(RetirementDemand{copy_bytes:self.frames.next_reserve_copy_byte_demand().map_err(page_error)?,capacity_bytes:self.frames.next_allocation_bytes().map_err(page_error)?,depth:self.frames.next_reserve_depth_demand().map_err(page_error)?,..Default::default()})}
 fn pop_demands(&self)->Result<RetirementDemand,ValueError>{Ok(RetirementDemand{copy_bytes:2*size_of::<Frame>()+META,depth:self.frames.next_pop_depth_demand().map_err(page_error)?,..Default::default()})}
 fn release_frames_demands(&self)->Result<RetirementDemand,ValueError>{Ok(RetirementDemand{release_bytes:self.frames.next_release_allocation_bytes().map_err(page_error)?,depth:self.frames.next_release_depth_demand().map_err(page_error)?,..Default::default()})}
 pub fn demands(&self)->Result<Option<RetirementDemand>,ValueError>{if self.closing{return self.close_demands().map(Some)}if self.pending.is_some(){return Ok(Some(RetirementDemand{copy_bytes:ATTACH,depth:1,..Default::default()}))}if !self.started{return Ok(Some(if !self.frames.has_reserved_slot(){self.reserve_demands()?}else{header::<(Frame,Frame,bool)>()}))}if self.finished{if !self.frames.terminal_is_empty(){return self.release_frames_demands().map(Some)}return Ok(Some(header::<(Option<UiValue>,Option<UiValue>)>()))}let frame=self.frames.last().ok_or_else(invalid)?;let d=match frame.phase{0=>{let Some(info)=self.info(frame.location)?else{return Ok(None)};let capacity_bytes=match info.kind{Kind::Text=>info.length,Kind::List=>info.length.checked_mul(size_of::<DslValue>()).ok_or_else(invalid)?,Kind::Map=>info.length.checked_mul(size_of::<(String,DslValue)>()).ok_or_else(invalid)?,_=>0};RetirementDemand{copy_bytes:size_of::<Frame>(),capacity_bytes,depth:1,..Default::default()}},1=>{let Some((_,count))=self.text(frame.location,frame.offset)?else{return Ok(None)};RetirementDemand{copy_bytes:2*count+META,depth:1,..Default::default()}},2=>{if frame.index==frame.length{header::<u8>()}else if matches!(frame.value,Some(DslValue::Object(_))){let Some((_,_,length))=self.key(frame.next,0)?else{return Ok(None)};RetirementDemand{copy_bytes:2*size_of::<Option<String>>()+META,capacity_bytes:length,depth:1,..Default::default()}}else{header::<u8>()}},3=>{let Some((_,count,_))=self.key(frame.next,frame.offset)?else{return Ok(None)};RetirementDemand{copy_bytes:2*count+META,depth:1,..Default::default()}},4=>if !self.frames.has_reserved_slot(){self.reserve_demands()?}else{header::<(Frame,Frame,usize,u8)>()},5=>self.pop_demands()?,_=>return Err(invalid())};let mut d=d;d.depth=d.depth.max(self.frames.len()+usize::from(frame.phase==4)).max(1);Ok(Some(d))}
 pub fn ready(&self)->bool{!self.closing&&self.finished&&self.input.is_none()&&self.frames.terminal_is_empty()&&self.pending.is_none()&&self.output.is_some()}
 /// 🌿️ One original turn reads one arena node or bounded text prefix and writes only its final canonical owner.
 pub fn advance(&mut self,input:&mut Option<UiValue>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(input,cx)?;if self.closing{return Err(invalid().into())}if self.ready(){return Ok(true)}if self.terminal_is_empty(){return Err(invalid().into())}let Some(d)=self.demands()?else{return Ok(false)};turn(cx,d,|effect|self.drive(input,effect,d))?;Ok(self.ready())}
 fn drive(&mut self,input:&mut Option<UiValue>,effect:&mut RetainedAllocationEffect<'_>,d:RetirementDemand)->Result<RetainedCloneProgress,ValueError>{if self.pending.is_some(){pay(effect)?;let root=self.frames.is_empty();let pending=self.pending.as_mut().ok_or_else(invalid)?;let value=pending.value.take().ok_or_else(invalid)?;if root{*self.output=Some(value);self.finished=true;}else{let parent=self.frames.last_mut().ok_or_else(invalid)?;match parent.value.as_mut().ok_or_else(invalid)?{DslValue::Array(rows)=>rows.push(value),DslValue::Object(rows)=>rows.push((parent.key.take().ok_or_else(invalid)?,value)),_=>return Err(invalid())}parent.index+=1;parent.phase=2;}self.pending.take();return Ok(receipt(d))}if !self.started{if !self.frames.has_reserved_slot(){return reserved(self.frames.reserve_one_funded(effect))}pay(effect)?;self.frames.push_reserved(Frame::new(Location::Root)).map_err(|_|invalid())?;self.started=true;return Ok(receipt(d))}if self.finished{if !self.frames.terminal_is_empty(){return released(self.frames.release_empty_page(effect))}pay(effect)?;*input=self.input.take();return Ok(receipt(d))}let(location,phase,next,offset)=self.frames.last().map(|frame|(frame.location,frame.phase,frame.next,frame.offset)).ok_or_else(invalid)?;match phase{
 0=>{pay(effect)?;let Some(info)=self.info(location)?else{return Ok(Default::default())};let value=match info.kind{Kind::Null=>DslValue::Null,Kind::Bool(value)=>DslValue::Bool(value),Kind::Number(value)=>number(value),Kind::Text=>{let mut text=String::new();text.try_reserve_exact(info.length).map_err(|_|invalid())?;DslValue::String(text)},Kind::List=>{let mut rows=Vec::new();rows.try_reserve_exact(info.length).map_err(|_|invalid())?;DslValue::Array(rows)},Kind::Map=>{let mut rows=Vec::new();rows.try_reserve_exact(info.length).map_err(|_|invalid())?;DslValue::Object(rows)}};let frame=self.frames.last_mut().ok_or_else(invalid)?;frame.value=Some(value);frame.length=info.length;frame.next=info.head;frame.phase=match info.kind{Kind::Text=>1,Kind::List|Kind::Map=>2,_=>5};},
 1=>{pay(effect)?;let Some((bytes,count))=self.text(location,offset)?else{return Ok(Default::default())};let frame=self.frames.last_mut().ok_or_else(invalid)?;let Some(DslValue::String(text))=frame.value.as_mut()else{return Err(invalid())};text.push_str(std::str::from_utf8(&bytes[..count]).map_err(|_|invalid())?);frame.offset+=count;if frame.offset==frame.length{frame.phase=5;}},
 2=>{pay(effect)?;let frame=self.frames.last_mut().ok_or_else(invalid)?;if frame.index==frame.length{frame.phase=5;}else if matches!(frame.value,Some(DslValue::Object(_))){let Some((_,_,length))=self.key(next,0)?else{return Ok(Default::default())};let mut key=String::new();key.try_reserve_exact(length).map_err(|_|invalid())?;let frame=self.frames.last_mut().ok_or_else(invalid)?;frame.key=Some(key);frame.offset=0;frame.phase=3;}else{frame.phase=4;}},
 3=>{pay(effect)?;let Some((bytes,count,length))=self.key(next,offset)?else{return Ok(Default::default())};let frame=self.frames.last_mut().ok_or_else(invalid)?;frame.key.as_mut().ok_or_else(invalid)?.push_str(std::str::from_utf8(&bytes[..count]).map_err(|_|invalid())?);frame.offset+=count;if frame.offset==length{frame.phase=4;}},
 4=>{if !self.frames.has_reserved_slot(){return reserved(self.frames.reserve_one_funded(effect))}pay(effect)?;let Some((location,following))=self.with_page(next,|page|Ok((Location::Page{index:next,epoch:page.epoch},page.next)))?else{return Ok(Default::default())};self.frames.last_mut().ok_or_else(invalid)?.next=following;self.frames.push_reserved(Frame::new(location)).map_err(|_|invalid())?;},
 5=>{pay(effect)?;*self.pending=self.frames.pop();},_=>return Err(invalid())}Ok(receipt(d))}
 pub fn take_demands(&self)->Result<RetirementDemand,ValueError>{if !self.ready(){return Err(invalid())}Ok(header::<(Option<DslValue>,Option<DslValue>)>())}
 /// 🤝️ Output becomes available only after the exact original UI input returned to its receiving slot.
 pub fn take_into(&mut self,output:&mut Option<DslValue>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if !self.binding.matches(cx)||cx.native_receiving_identity()!=Some(self.decoder){return Err(invalid().into())}let d=self.take_demands()?;turn(cx,d,|effect|{pay(effect)?;*output=Some(self.output.take().ok_or_else(invalid)?);Ok(receipt(d))})}
 pub fn close_demands(&self)->Result<RetirementDemand,ValueError>{if !self.closing{return Ok(header::<bool>())}if !self.retirement.is_empty(){return self.retirement.demands(self.body)}if self.pending.is_some(){return self.retirement.next_owner_demands::<Frame>(true,&None,self.body)}if !self.frames.is_empty(){return self.pop_demands()}if !self.frames.terminal_is_empty(){return self.release_frames_demands()}if self.output.is_some(){return self.retirement.next_owner_demands::<DslValue>(true,&None,self.body)}if self.input.is_some(){return Ok(header::<(Option<UiValue>,Option<UiValue>)>())}Ok(Default::default())}
 /// ♻️ Cancellation retires only private converted owners and restores the same original arena input before terminal release.
 pub fn close_step(&mut self,input:&mut Option<UiValue>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(input,cx)?;if self.terminal_is_empty(){return Ok(true)}let d=self.close_demands()?;close_original_effect_step(cx,d,|effect|{
  macro_rules! pure{($body:expr)=>{{if let Err(error)=pay(effect){return closed(effect,Err(error))}$body;return closed(effect,Ok(RetainedCloneStep::Progress(receipt(d))))}}}
  if !self.closing{pure!(self.closing=true)}
  if !self.retirement.is_empty(){return self.retirement.step_granted(effect)}
  if self.pending.is_some(){return begun(self.retirement.begin_granted(&mut self.pending,effect))}
  if !self.frames.is_empty(){pure!(*self.pending=self.frames.pop())}
  if !self.frames.terminal_is_empty(){let turn=self.frames.release_empty_page(effect);let work=turn.work;return RetainedWorkPoll::Complete(RetainedWorkOutcome{result:released(turn).map(RetainedCloneStep::Progress).map_err(Into::into),work})}
  if self.output.is_some(){return begun(self.retirement.begin_granted(&mut self.output,effect))}
  if self.input.is_some(){pure!(*input=self.input.take())}
  closed(effect,Ok(RetainedCloneStep::Complete(Default::default())))
 })?;Ok(self.terminal_is_empty())}
 pub fn terminal_is_empty(&self)->bool{self.input.is_none()&&self.frames.terminal_is_empty()&&self.pending.is_none()&&self.output.is_none()&&self.retirement.is_empty()}
 pub fn release_demands()->RetirementDemand{RetirementDemand{release_bytes:size_of::<Self>(),depth:1,..Default::default()}}
}
fn fragment(text:&str,offset:usize)->Result<([u8;64],usize),ValueError>{if offset>text.len()||!text.is_char_boundary(offset){return Err(invalid())}let mut end=(offset+64).min(text.len());while !text.is_char_boundary(end){end-=1}let mut bytes=[0;64];let count=end-offset;bytes[..count].copy_from_slice(&text.as_bytes()[offset..end]);Ok((bytes,count))}
fn number(value:f64)->DslValue{match semio_framework_value::json_integer(value){Some(semio_framework_value::JsonInteger::Signed(value))=>DslValue::Number(Number::Int(value)),Some(semio_framework_value::JsonInteger::Unsigned(value))=>DslValue::Number(Number::UInt(value)),None if value.is_finite()=>DslValue::Number(Number::Float(value)),None=>DslValue::Null}}
impl Drop for OriginalUiValueConversion{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original UI conversion must return its input and retire all private owners")}}

